package com.trampolim.api.trust;
import java.util.*;import java.time.*;
import com.trampolim.api.security.PlatformAccess;import com.trampolim.api.radar.RadarBridge;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service @ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class CompanyTrustService {
 private final JdbcTemplate db;private final PlatformAccess platform;private final RadarBridge bridge;
 private static final String HASH="md5(concat_ws('|',c.owner_user_id,u.email,c.cnpj,c.legal_name,c.trade_name,c.phone,c.website,c.address,c.city,c.state))";
 public CompanyTrustService(@Qualifier("empresasJdbcTemplate")JdbcTemplate db,PlatformAccess platform,RadarBridge bridge){this.db=db;this.platform=platform;this.bridge=bridge;}
 public record Verification(long expectedRevision,boolean approved,boolean registryActive,boolean legalNameMatches,boolean representativeConfirmed,boolean contactConfirmed,String sourceReference,String checkedAt,String reason){}
 public record ListingDecision(long expectedRevision,String action,String reason){}public record Appeal(String reason){}
 public record Report(UUID receipt,long listingId,String origin,String reason,String details){}public record Withdrawal(UUID receipt){}public record ReportDecision(long expectedRevision,String action,String reason){}
 private static void bad(String reason){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,reason);}private static void missing(){throw new ResponseStatusException(HttpStatus.NOT_FOUND);}private static void conflict(){throw new ResponseStatusException(HttpStatus.CONFLICT,"O registro mudou; consulte a revisão atual.");}
 private String text(String value,int max,int min){String s=value==null?"":value.trim();if(s.length()>max||s.length()<min||s.indexOf(0)>=0)bad("Revise o preenchimento e os limites dos campos.");return s;}
 public void admin(String email){if(!platform.isSuperAdmin(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 public long company(String email){var rows=db.queryForList("SELECT c.id FROM companies c JOIN company_users u ON u.id=c.owner_user_id OR EXISTS(SELECT 1 FROM company_members m WHERE m.company_id=c.id AND m.user_id=u.id AND m.role IN ('OWNER','ADMIN','RECRUITER')) WHERE LOWER(u.email)=LOWER(?) AND u.email_verified=TRUE AND u.account_status='ACTIVE' ORDER BY c.id LIMIT 1",Long.class,email);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.FORBIDDEN);return rows.getFirst();}
 private Map<String,Object> profile(long id,boolean lock){return db.queryForList("SELECT c.*,"+HASH+" AS profile_hash,u.email_verified,u.account_status FROM companies c JOIN company_users u ON u.id=c.owner_user_id WHERE c.id=?"+(lock?" FOR UPDATE OF c":""),id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
 private void independent(String email,long company){if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM companies c JOIN company_users u ON u.id=c.owner_user_id OR EXISTS(SELECT 1 FROM company_members m WHERE m.company_id=c.id AND m.user_id=u.id) WHERE c.id=? AND LOWER(u.email)=LOWER(?))",Boolean.class,company,email)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"A revisão deve ser independente da empresa.");}
 private void complete(Map<String,Object> p){if(!Cnpj.valid(p.get("cnpj").toString()))bad("O CNPJ precisa ter formato e dígitos verificadores válidos; dados legados não foram apagados.");for(String key:List.of("legal_name","trade_name","phone","industry","address","city","state"))if(Objects.toString(p.get(key),"").isBlank())bad("Cadastro empresarial incompleto.");if(!Boolean.TRUE.equals(p.get("email_verified"))||!p.get("account_status").equals("ACTIVE"))bad("Responsável precisa de conta ativa com e-mail verificado.");}
 private void audit(long company,Long listing,String actor,String action,String reason){db.update("INSERT INTO company_trust_audit(company_id,listing_id,actor,action,reason) VALUES (?,?,?,?,?)",company,listing,actor,action,reason);}
 private void notify(long company,long resource,String key){db.update("INSERT INTO communication_events(source_key,kind,resource_id,scope_id) VALUES (?,'TRUST_REVIEW',?,?) ON CONFLICT DO NOTHING",key,resource,company);}
 @Transactional("empresasTransactionManager")public Map<String,Object> request(String email){long company=company(email);var p=profile(company,true);complete(p);var old=db.queryForList("SELECT id,state,revision,profile_hash FROM company_trust_cases WHERE company_id=? AND state IN ('REQUESTED','UNDER_REVIEW')",company);if(!old.isEmpty()){if(old.getFirst().get("profile_hash").equals(p.get("profile_hash"))){var result=new LinkedHashMap<>(old.getFirst());result.remove("profile_hash");return result;}db.update("UPDATE company_trust_cases SET state='REJECTED',revision=revision+1,decision_reason='Perfil alterado; nova solicitação necessária.' WHERE id=?",old.getFirst().get("id"));}if(db.queryForObject("SELECT count(*) FROM company_trust_cases WHERE company_id=? AND created_at>CURRENT_TIMESTAMP-INTERVAL '1 day'",Integer.class,company)>=3)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS);long id=db.queryForObject("INSERT INTO company_trust_cases(company_id,profile_hash) VALUES (?,?) RETURNING id",Long.class,company,p.get("profile_hash"));audit(company,null,email,"VERIFICATION_REQUESTED","");return Map.of("id",id,"state","REQUESTED","revision",1);}
 public List<Map<String,Object>> own(String email){return db.queryForList("SELECT id,state,revision,created_at,expires_at,decision_reason FROM company_trust_cases WHERE company_id=? ORDER BY id DESC LIMIT 50",company(email));}
 public Map<String,Object> queue(String email,long before,int limit){admin(email);page(before,limit);var rows=db.queryForList("SELECT t.id,t.company_id,t.state,t.revision,t.created_at,c.trade_name FROM company_trust_cases t JOIN companies c ON c.id=t.company_id WHERE t.id<? ORDER BY t.id DESC LIMIT ?",before,limit+1);return page(rows,limit);}
 public Map<String,Object> inspect(String email,long id){admin(email);var c=db.queryForList("SELECT * FROM company_trust_cases WHERE id=?",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));var p=profile(((Number)c.get("company_id")).longValue(),false);p.remove("profile_hash");c.put("company",p);return c;}
 @Transactional("empresasTransactionManager")public Map<String,Object> decide(String email,long id,Verification input){admin(email);if(input==null)bad("Informe a decisão e os critérios.");var root=db.queryForList("SELECT company_id FROM company_trust_cases WHERE id=?",Long.class,id);if(root.isEmpty())missing();long company=root.getFirst();var p=profile(company,true);independent(email,company);var t=db.queryForMap("SELECT * FROM company_trust_cases WHERE id=? FOR UPDATE",id);if(((Number)t.get("revision")).longValue()!=input.expectedRevision()||!Set.of("REQUESTED","UNDER_REVIEW").contains(t.get("state")))conflict();String reason=text(input.reason(),1000,20);Instant checked=null;String source="";if(input.approved()){complete(p);if(!p.get("profile_hash").equals(t.get("profile_hash")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Cadastro mudou após a solicitação; abra nova revisão.");if(!input.registryActive()||!input.legalNameMatches()||!input.representativeConfirmed()||!input.contactConfirmed())bad("Todos os critérios objetivos precisam de comprovação independente.");source=text(input.sourceReference(),500,20);try{checked=Instant.parse(input.checkedAt());}catch(Exception e){bad("Informe a data da consulta oficial com fuso ISO-8601.");}if(checked.isAfter(Instant.now().plusSeconds(60))||checked.isBefore(Instant.now().minus(Duration.ofDays(30))))bad("Use consulta realizada nos últimos trinta dias.");}
 db.update("UPDATE company_trust_cases SET state=?,revision=revision+1,source_reference=?,registry_checked_at=?,expires_at=CASE WHEN ? THEN CURRENT_TIMESTAMP+INTERVAL '90 days' ELSE NULL END,decision_reason=?,reviewed_by=? WHERE id=?",input.approved()?"APPROVED":"REJECTED",source,checked==null?null:java.sql.Timestamp.from(checked),input.approved(),reason,email,id);db.update("UPDATE companies SET verification_status=? WHERE id=?",input.approved()?"APPROVED":"REJECTED",company);audit(company,null,email,input.approved()?"VERIFICATION_APPROVED":"VERIFICATION_REJECTED",reason);notify(company,company,"trust:company:"+id+":"+(input.expectedRevision()+1));return Map.of("state",input.approved()?"APPROVED":"REJECTED","revision",input.expectedRevision()+1,"notice","Revisão manual de cadastro, não garantia de idoneidade ou de contratação.");}
 public boolean proof(long company){return Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM company_trust_cases t JOIN companies c ON c.id=t.company_id JOIN company_users u ON u.id=c.owner_user_id WHERE c.id=? AND t.state='APPROVED' AND t.id=(SELECT max(last.id) FROM company_trust_cases last WHERE last.company_id=c.id AND last.state IN ('APPROVED','REJECTED')) AND t.profile_hash="+HASH+" AND t.expires_at>CURRENT_TIMESTAMP AND u.email_verified=TRUE AND u.account_status='ACTIVE')",Boolean.class,company));}
 public Map<String,Object> badge(String slug){var ids=db.queryForList("SELECT id FROM companies WHERE public_slug=? AND verification_status='APPROVED'",Long.class,slug);if(ids.isEmpty())missing();long company=ids.getFirst();boolean verified=proof(company);var out=new LinkedHashMap<String,Object>();out.put("verified",verified);out.put("label",verified?"Cadastro empresarial revisado":"Sem selo de cadastro revisado vigente");if(verified)out.put("validUntil",db.queryForObject("SELECT expires_at FROM company_trust_cases t JOIN companies c ON c.id=t.company_id JOIN company_users u ON u.id=c.owner_user_id WHERE t.company_id=? AND t.state='APPROVED' AND t.profile_hash="+HASH+" ORDER BY t.id DESC LIMIT 1",java.sql.Timestamp.class,company));out.put("scope","Situação cadastral, correspondência do nome, representante e contato revisados manualmente. Não garante segurança de toda vaga nem contratação.");return out;}
 public Map<String,Object> listing(String email,long id){long company=company(email);var rows=db.queryForList("SELECT id,risk_state,risk_signals,trust_revision,publication_status FROM company_listings WHERE id=? AND company_id=?",id,company);if(rows.isEmpty())missing();var row=rows.getFirst();row.put("risk_signals",bridge.convert(bridge.read(row.get("risk_signals")),List.class));return row;}
 public Map<String,Object> listings(String email,long before,int limit){admin(email);page(before,limit);return page(db.queryForList("SELECT l.id,l.company_id,l.title,l.publication_status,l.risk_state,l.risk_signals,l.trust_revision FROM company_listings l WHERE l.id<? AND (l.risk_state<>'CLEAR' OR EXISTS(SELECT 1 FROM company_listing_reports r WHERE r.listing_id=l.id AND r.status='OPEN')) ORDER BY l.id DESC LIMIT ?",before,limit+1).stream().map(r->{r.put("risk_signals",bridge.convert(bridge.read(r.get("risk_signals")),List.class));return r;}).toList(),limit);}
 @Transactional("empresasTransactionManager")public Map<String,Object> moderate(String email,long id,ListingDecision input){admin(email);if(input==null||!Set.of("ALLOW","HOLD").contains(Objects.toString(input.action(),"")))bad("Escolha liberar ou suspender de forma revisável.");String reason=text(input.reason(),1000,20);var roots=db.queryForList("SELECT company_id FROM company_listings WHERE id=?",Long.class,id);if(roots.isEmpty())missing();long company=roots.getFirst();profile(company,true);independent(email,company);var r=db.queryForMap("SELECT * FROM company_listings WHERE id=? FOR UPDATE",id);if(((Number)r.get("trust_revision")).longValue()!=input.expectedRevision())conflict();db.update("UPDATE company_listings SET risk_state=?,risk_approved_fingerprint=CASE WHEN ? THEN risk_fingerprint ELSE NULL END,publication_status=CASE WHEN publication_status='PUBLISHED' THEN 'PAUSED' ELSE publication_status END WHERE id=?",input.action().equals("ALLOW")?"CLEAR":"HELD",input.action().equals("ALLOW"),id);db.update("UPDATE company_listing_appeals SET state='RESOLVED' WHERE listing_id=? AND state='OPEN'",id);audit(company,id,email,input.action().equals("ALLOW")?"LISTING_ALLOWED":"LISTING_HELD",reason);return Map.of("riskState",input.action().equals("ALLOW")?"CLEAR":"HELD","revision",input.expectedRevision()+1,"notice","Liberação não publica automaticamente nem ignora pagamento, aprovação empresarial ou prazo.");}
 @Transactional("empresasTransactionManager")public Map<String,Object> appeal(String email,long id,Appeal input){long company=company(email);String reason=text(input==null?null:input.reason(),1000,20);profile(company,true);var listing=db.queryForList("SELECT risk_state FROM company_listings WHERE id=? AND company_id=? FOR UPDATE",id,company);if(listing.isEmpty())missing();if(listing.getFirst().get("risk_state").equals("CLEAR"))bad("O anúncio não possui bloqueio para revisão.");var existing=db.queryForList("SELECT id FROM company_listing_appeals WHERE listing_id=? AND state='OPEN'",Long.class,id);if(!existing.isEmpty())return Map.of("id",existing.getFirst(),"state","OPEN");if(db.queryForObject("SELECT count(*) FROM company_listing_appeals WHERE company_id=? AND created_at>CURRENT_TIMESTAMP-INTERVAL '1 day'",Integer.class,company)>=5)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS);long appeal=db.queryForObject("INSERT INTO company_listing_appeals(company_id,listing_id,reason) VALUES (?,?,?) RETURNING id",Long.class,company,id,reason);audit(company,id,email,"LISTING_APPEAL_REQUESTED",reason);return Map.of("id",appeal,"state","OPEN");}
 public Map<String,Object> appeals(String email,long before,int limit){admin(email);page(before,limit);return page(db.queryForList("SELECT * FROM company_listing_appeals WHERE id<? AND state='OPEN' ORDER BY id DESC LIMIT ?",before,limit+1),limit);}
 @Transactional("empresasTransactionManager")public Map<String,Object> receive(String key,Report p){bridge.authorize(key);if(p==null||p.receipt()==null||p.listingId()<1||!Set.of("OPORTUNIDADES","CAPACITA").contains(Objects.toString(p.origin(),""))||!Set.of("PAYMENT_REQUEST","IDENTITY_MISUSE","MISLEADING","DUPLICATE","OTHER").contains(Objects.toString(p.reason(),"")))bad("Denúncia inválida.");String details=text(p.details(),1000,0),hash=RadarBridge.hash(bridge.encode(List.of(p.listingId(),p.origin(),p.reason(),details)));db.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(rs,n)->0,p.receipt().toString());if(db.queryForObject("SELECT count(*) FROM company_report_tombstones WHERE receipt=?",Integer.class,p.receipt())>0)return Map.of("status","WITHDRAWN");var prior=db.queryForList("SELECT payload_hash,status FROM company_listing_reports WHERE receipt=?",p.receipt());if(!prior.isEmpty()){if(!prior.getFirst().get("payload_hash").equals(hash))conflict();return Map.of("status",prior.getFirst().get("status"));}if(db.queryForObject("SELECT count(*) FROM company_listings l WHERE l.id=? AND l.kind='job' AND (l.publication_status='PUBLISHED' OR EXISTS(SELECT 1 FROM career_listing_publications p WHERE p.listing_id=l.id))",Integer.class,p.listingId())==0)missing();db.update("INSERT INTO company_listing_reports(receipt,listing_id,origin,reason,details,payload_hash) VALUES (?,?,?,?,?,?)",p.receipt(),p.listingId(),p.origin(),p.reason(),details,hash);return Map.of("status","OPEN","notice","Denúncia encaminhada para análise humana; não prova fraude nem bloqueia automaticamente.");}
 @Transactional("empresasTransactionManager")public void withdraw(String key,Withdrawal p){bridge.authorize(key);if(p==null||p.receipt()==null)bad("Recibo inválido.");db.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(rs,n)->0,p.receipt().toString());db.update("INSERT INTO company_report_tombstones(receipt) VALUES (?) ON CONFLICT DO NOTHING",p.receipt());db.update("UPDATE company_listing_reports SET details='',status='WITHDRAWN',decision_reason=NULL,reviewed_by=NULL,revision=revision+1 WHERE receipt=? AND status<>'WITHDRAWN'",p.receipt());}
 public Map<String,Object> reports(String email,long before,int limit){admin(email);page(before,limit);return page(db.queryForList("SELECT l.id,l.company_id,l.title,count(r.receipt) AS open_reports FROM company_listings l JOIN company_listing_reports r ON r.listing_id=l.id AND r.status='OPEN' WHERE l.id<? GROUP BY l.id ORDER BY l.id DESC LIMIT ?",before,limit+1),limit);}
 public List<Map<String,Object>> reportDetails(String email,long listing,UUID before,int limit){admin(email);if(limit<1||limit>50)bad("Use até cinquenta relatos por página.");return db.queryForList("SELECT receipt,origin,reason,details,status,revision,created_at FROM company_listing_reports WHERE listing_id=? AND (?::uuid IS NULL OR receipt<?::uuid) ORDER BY receipt DESC LIMIT ?",listing,before,before,limit);}
 @Transactional("empresasTransactionManager")public void decideReport(String email,UUID receipt,ReportDecision input){admin(email);if(input==null||!Set.of("RESOLVED","DISMISSED").contains(Objects.toString(input.action(),"")))bad("Decisão inválida.");String reason=text(input.reason(),1000,20);var root=db.queryForList("SELECT l.company_id,r.listing_id FROM company_listing_reports r JOIN company_listings l ON l.id=r.listing_id WHERE r.receipt=?",receipt);if(root.isEmpty())missing();long company=((Number)root.getFirst().get("company_id")).longValue();profile(company,true);independent(email,company);if(db.update("UPDATE company_listing_reports SET status=?,decision_reason=?,reviewed_by=?,revision=revision+1 WHERE receipt=? AND status='OPEN' AND revision=?",input.action(),reason,email,receipt,input.expectedRevision())==0)conflict();audit(company,((Number)root.getFirst().get("listing_id")).longValue(),email,"REPORT_REVIEWED",reason);}
 public List<Map<String,Object>> history(String email,long company,long before,int limit){admin(email);page(before,limit);return db.queryForList("SELECT id,listing_id,actor,action,reason,created_at FROM company_trust_audit WHERE company_id=? AND id<? ORDER BY id DESC LIMIT ?",company,before,limit);}
 private static void page(long before,int limit){if(before<1||limit<1||limit>50)bad("Use páginas de até cinquenta registros.");}private static Map<String,Object> page(List<Map<String,Object>> rows,int limit){return com.trampolim.api.hub.HubService.pageResult(rows,limit);}
 public Map<String,Object> reportStatus(String key,Withdrawal p){bridge.authorize(key);if(p==null||p.receipt()==null)bad("Recibo inválido.");var rows=db.queryForList("SELECT status,revision FROM company_listing_reports WHERE receipt=?",p.receipt());return rows.isEmpty()?Map.of("status","PENDING"):rows.getFirst();}
 @Transactional("empresasTransactionManager")public Map<String,Object> start(String email,long id,long revision){admin(email);var roots=db.queryForList("SELECT company_id FROM company_trust_cases WHERE id=?",Long.class,id);if(roots.isEmpty())missing();long company=roots.getFirst();profile(company,true);independent(email,company);if(db.update("UPDATE company_trust_cases SET state='UNDER_REVIEW',revision=revision+1 WHERE id=? AND state='REQUESTED' AND revision=?",id,revision)==0)conflict();audit(company,null,email,"VERIFICATION_STARTED","");return Map.of("state","UNDER_REVIEW","revision",revision+1);}
 @Transactional("empresasTransactionManager")public Map<String,Object> rescan(String email,long id){admin(email);var roots=db.queryForList("SELECT company_id FROM company_listings WHERE id=?",Long.class,id);if(roots.isEmpty())missing();profile(roots.getFirst(),true);db.update("UPDATE company_listings SET updated_at=CURRENT_TIMESTAMP WHERE id=?",id);audit(roots.getFirst(),id,email,"LISTING_RESCANNED","");var result=db.queryForMap("SELECT id,risk_state,risk_signals,trust_revision,publication_status FROM company_listings WHERE id=?",id);result.put("risk_signals",bridge.convert(bridge.read(result.get("risk_signals")),List.class));return result;}
}
